import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path

class PageText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts = []
        self.hidden = 0
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.hidden += 1
    def handle_endtag(self, tag):
        if tag in ('script', 'style') and self.hidden:
            self.hidden -= 1
    def handle_data(self, data):
        if not self.hidden and data.strip():
            self.parts.append(data.strip())

root = Path('products/distribution/sqlite-lemonsqueezy-fit')
path = root / 'raw/fees.html'
raw = path.read_bytes()
parser = PageText()
parser.feed(raw.decode('utf-8'))
text = re.sub(r'\s+', ' ', ' '.join(parser.parts))
blocks = [m.group(0) for m in re.finditer(r'Payout fees.{0,1700}?Marketing fees', text, re.I) if 'bank accounts outside' in m.group(0).lower()]
report = {'source': 'https://docs.lemonsqueezy.com/help/getting-started/fees', 'sha256': hashlib.sha256(raw).hexdigest(), 'status': 'passage_found' if blocks else 'passage_not_located', 'payout_fee_passages': list(dict.fromkeys(blocks)), 'decision_use': 'Compare bank and PayPal payout charges for the contemplated Canadian seller. Confirm country applicability, settlement currency, threshold and timing in payout documentation before quoting realizable proceeds. This fee page alone cannot verify onboarding, archive rights, or settlement.'}
out = root / 'director-payout-fee-evidence.json'
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(report, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(out.read_text(encoding='utf-8'))
